 const submit=async(e:FormEvent)=>{e.preventDefault();if(!modal)return;let command:unknown;if(modal.type==='store'){const keys=['name','legalName','cnpj','ie','regime','uf','city','municipalityCode','address','number','district','zip'];const fields=Object.fromEntries(keys.map(k=>[k,(values[k]??'').trim()]));for(const k of ['cnpj','zip','municipalityCode'])fields[k]=fields[k].replace(/\D/g,'');fields.uf=fields.uf.toUpperCase();command={type:modal.id?'store.update':'store.create',...(modal.id?{id:modal.id}:{}),data:fields}}if(modal.type==='product'){const keys=['name','sku','barcode','ncm','cest','cfop','origin','taxCode','unit'];const fields={...Object.fromEntries(keys.map(k=>[k,(values[k]??'').trim()])),price:toCents(values.price),cost:toCents(values.cost),minimum:Number(values.minimum)};command={type:modal.id?'product.update':'product.create',...(modal.id?{id:modal.id}:{}),data:fields}}if(modal.type==='customer'){const keys=['name','document','docType','ie','indIeDest','email','phone','zip','address','number','complement','district','city','state','municipalityCode'];const payload:Record<string,string>={};for(const k of keys){const val=(values[k]??'').trim();if(val)payload[k]=val;}if(payload.document)payload.document=payload.document.replace(/\D/g,'');if(payload.zip)payload.zip=payload.zip.replace(/\D/g,'');if(payload.municipalityCode)payload.municipalityCode=payload.municipalityCode.replace(/\D/g,'');if(payload.state)payload.state=payload.state.toUpperCase();command={type:modal.id?'customer.update':'customer.create',...(modal.id?{id:modal.id}:{}),data:payload};}if(modal.type==='supplier'){const keys=['name','tradeName','document','docType','ie','email','phone','contactName','zip','address','number','complement','district','city','state','municipalityCode'];const payload:Record<string,string>={};for(const k of keys){const val=(values[k]??'').trim();if(val)payload[k]=val;}if(payload.document)payload.document=payload.document.replace(/\D/g,'');if(payload.zip)payload.zip=payload.zip.replace(/\D/g,'');if(payload.municipalityCode)payload.municipalityCode=payload.municipalityCode.replace(/\D/g,'');if(payload.state)payload.state=payload.state.toUpperCase();command={type:modal.id?'supplier.update':'supplier.create',...(modal.id?{id:modal.id}:{}),data:payload};}if(modal.type==='receive')command={type:'stock.receive',storeId:values.storeId,productId:values.productId,qty:Number(values.qty),reason:values.reason};if(modal.type==='transfer')command={type:'transfer.create',from:values.from,to:values.to,productId:values.productId,qty:Number(values.qty)};if(modal.type==='cash.open')command={type:'cash.open',storeId:values.storeId,opening:toCents(values.opening)};if(modal.type==='cash.close')command={type:'cash.close',id:modal.id,counted:toCents(values.counted)};if(modal.type==='cash.supply')command={type:'cash.supply',id:modal.id,amount:toCents(values.amount),reason:values.reason};if(modal.type==='cash.withdrawal')command={type:'cash.withdrawal',id:modal.id,amount:toCents(values.amount),reason:values.reason};if(modal.type==='sale.cancel')command={type:'sale.cancel',id:modal.id,reason:values.reason};if(modal.type==='nfe.cancel')command={type:'fiscal.nfe.cancel',saleId:modal.id,justification:values.justification};if(modal.type==='sale.return'){const sr=state?.sales.find(x=>x.id===modal.id);const items=(sr?.items??[]).map(i=>({productId:i.productId,qty:Number(values['qty_'+i.productId]||0),restock:values['restock_'+i.productId]!=='0'})).filter(i=>i.qty>0);if(!items.length){setFormError('Informe a quantidade de ao menos um item.');return}command={type:'sale.return',saleId:modal.id,items,reason:values.reason,refundMethod:values.refundMethod}}if(modal.type==='user.assign')command={type:'user.assign',userId:(values.userId??'').trim(),displayName:(values.displayName??'').trim(),role:values.role,storeId:values.storeId||null};if(await act(command))setModal(null)};
 const add=(p:Product,delta:number)=>{if(!operational)return;const stock=state?.stock[operational.id]?.[p.id]??0;setCart(c=>{const count=Math.max(0,Math.min(stock,(c[p.id]??0)+delta));const next={...c};if(count)next[p.id]=count;else delete next[p.id];return next})};
 const finish=async()=>{if(!operational)return;const lines=paymentLines.filter(l=>l.amount!=='');const payments=lines.length?lines.map(l=>({method:l.method,amount:toCents(l.amount)})):[{method:paymentLines[0]?.method??'Dinheiro',amount:netNow}];const command:Record<string,unknown>={type:'sale.create',storeId:operational.id,items:Object.entries(cart).map(([productId,qty])=>({productId,qty})),payments,customer,document:documentNumber.replace(/\D/g,'')};if(discountNow>0){command.discount=discountMode==='percent'?{percent:Number(discountValue.replace(',','.')),reason:discountReason}:{amount:toCents(discountValue),reason:discountReason};if(needSupervisor&&supervisorEmail&&supervisorPassword)command.authorization={email:supervisorEmail,password:supervisorPassword}}const result=await act(command);if(result){setCart({});setCustomer('');setDocumentNumber('');setPaymentLines([{method:'Dinheiro',amount:''}]);setDiscountOn(false);setDiscountValue('');setDiscountReason('');setNeedSupervisor(false);setSupervisorEmail('');setSupervisorPassword('');const sale=result.state.sales.find(s=>s.id===result.resultId);if(sale){setReceipt(sale);setModal({type:'receipt'})}}else if(lastStatus.current===428)setNeedSupervisor(true);else if(lastStatus.current===403)setSupervisorPassword('')};
 const print=async()=>{if(!receipt)return;const result=await act({type:'sale.print',id:receipt.id});if(result){const updated=result.state.sales.find(s=>s.id===receipt.id);if(updated)setReceipt(updated);setTimeout(()=>window.print(),80)}};
 const exportData=()=>{if(!data)return;const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),account:data.account,state:data.state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='omnihub-dados.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
