 function storeCard(s:StoreRecord){const units=Object.values(state?.stock[s.id]??{}).reduce((a,b)=>a+b,0);const fCfg=state?.fiscalConfigs?.[s.id];const cert=fCfg?.certificate;const nCfg=state?.nfceConfigs?.[s.id];return <section className="panel store-card" key={s.id}><div className="split"><div className="store-icon"><Store/></div><span className="badge neutral">{s.uf||'Loja'}</span></div><h2>{s.name}</h2><p className="muted">{s.cnpj?'CNPJ '+s.cnpj:'Dados fiscais a completar'}</p><div className="split" style={{marginTop:22}}><span className="muted">Estoque disponível</span><strong>{units} un.</strong></div><div className="mt-4 flex flex-wrap gap-1"><span className="badge neutral">NF-e 55: Homologação</span>{cert?.status==='VALID'?<span className="badge success">Certificado A1 OK</span>:cert?.status==='EXPIRING'?<span className="badge warning">Certificado A1 expirando</span>:cert?.status==='EXPIRED'?<span className="badge error">Certificado A1 expirado</span>:<span className="badge neutral">Sem certificado A1</span>}<span className="badge neutral">NFC-e 65: Homologação</span>{nCfg?.status==='READY'?<span className="badge success">NFC-e pronta</span>:nCfg?.status==='CONFIGURED'?<span className="badge warning">NFC-e incompleta</span>:<span className="badge neutral">NFC-e não configurada</span>}</div><div className="form-actions flex-wrap">{admin&&<Button variant="outline" size="sm" onClick={()=>open('fiscal',s)}><FileText size={16}/> Configuração fiscal</Button>}{admin&&<Button variant="outline" size="sm" onClick={()=>open('nfce',s)}><Send size={16}/> Configuração NFC-e</Button>}{canConfigPayments&&<Button variant="outline" size="sm" onClick={()=>open('payments',s)}><CreditCard size={16}/> Pagamentos integrados</Button>}<Button variant="outline" size="sm" onClick={()=>{if(Object.keys(cart).length){toast.error('Esvazie o carrinho antes de trocar de loja.');return}setStoreId(s.id);navigate('Produtos e estoque')}}>Ver estoque <ArrowUpRight/></Button>{admin&&<Button variant="ghost" size="icon" aria-label={'Editar '+s.name} disabled={!active} onClick={()=>open('store',s)}><Pencil size={16}/></Button>}</div></section>}
 const cartGrossNow=Object.entries(cart).reduce((a,[id,q])=>a+(products.find(p=>p.id===id)?.price??0)*q,0);const discountNumber=Number((discountValue||'0').replace(',','.'));const discountNow=discountOn&&discountNumber>0?(discountMode==='percent'?Math.floor(cartGrossNow*Math.round(discountNumber*100)/10000):toCents(discountValue)):0;const netNow=Math.max(cartGrossNow-discountNow,0);const canReturn=!!(data?.actor.permissions as unknown as string[]|undefined)?.includes('SALE_RETURN');
